survivors.original:
deploys.map((d) => {
      const start = this.events.find((e) => e.change === d.change && e.stage === first && e.kind === 'entered');
      return start ? (Date.parse(d.at) - Date.parse(start.at)) / 3_600_000 : NaN;
    }).filter((x) => !Number.isNaN(x))

survivors.replacement:
deploys.map(d => {
  const start = this.events.find(e => e.change === d.change && e.stage === first && e.kind === 'entered');
  return start ? (Date.parse(d.at) - Date.parse(start.at)) / 3_600_000 : NaN;
})
